(()=>{
const M=CivicModel,root=$('#civic-section');
let feed={topics:[],results:{}},feedError='',editing=null,progress=null,activeTopic=localStorage.getItem('civic-selected-topic')||null,landmarks={};
const option=(value,label=value)=>`<option value="${esc(value)}">${esc(label)}</option>`;
$('#civic-scope').innerHTML=option('全部')+M.scopes.map(s=>option(s)).join('');
$('#civic-scope').value=['全部',...M.scopes].includes(localStorage.getItem('civic-selected-scope'))?localStorage.getItem('civic-selected-scope'):'臺北市';
$('#civic-edit-scope').innerHTML=M.scopes.map(s=>option(s)).join('');
const topics=()=>[...new Map([...(feed.topics||[]),...issues.filter(i=>i.kind==='civic')].map(i=>[i.id,i])).values()];
function editable(id){let item=issues.find(i=>i.id===id);if(!item){item=structuredClone(topics().find(i=>i.id===id));if(!item)throw Error('找不到議題');issues.push(item)}return item}
const linksHtml=links=>(links||[]).filter(l=>M.safeUrl(l.url)).map(l=>`<a class="source-link" href="${esc(M.safeUrl(l.url))}" target="_blank" rel="noopener noreferrer">↗ ${esc(l.title||l.url)}</a>`).join('');
window.renderCivic=function(){
 const opened=new Set([...root.querySelectorAll('details[open]')].map(d=>d.dataset.detail));
 const q=M.normalize($('#civic-search').value),scope=$('#civic-scope').value;
 const list=topics().filter(i=>(scope==='全部'||i.scope===scope)&&M.normalize(i.name+' '+i.scope+' '+i.keys.join(' ')+' '+i.note).includes(q));
 if(!list.some(i=>i.id===activeTopic))activeTopic=list[0]?.id||null;
 if(activeTopic)localStorage.setItem('civic-selected-topic',activeTopic);
 $('#civic-scope-title').textContent=scope==='全部'?'全部議題':scope;
 $('#civic-city-tabs').innerHTML=['中央','臺北市','新北市','國際'].map(city=>`<button data-civic-city="${esc(city)}" class="${city===scope?'active':''}" aria-pressed="${city===scope}">${esc(city)}</button>`).join('');
 $('#civic-topic-tabs').innerHTML=list.map(i=>`<button class="${i.id===activeTopic?'active':''}" data-civic-topic="${esc(i.id)}" aria-pressed="${i.id===activeTopic}">${esc(i.name)}</button>`).join('');
 $('#civic-feed-status').textContent=feedError||'推薦隨每日資料更新'+(feed.updated?' · 最近檢查 '+new Date(feed.updated).toLocaleString('zh-TW',{timeZone:'Asia/Taipei',hour12:false}):' · 尚未取得新聞')+'；新增關鍵字於下次更新後取得推薦。';
 setLandmark(scope);
 const i=list.find(i=>i.id===activeTopic);
 if(!i){$('#civic-topics').innerHTML='<p class="civic-empty">這個範圍還沒有符合的議題。按「＋ 新增議題」，留下你想長期追蹤的方向。</p>';bindNavigation();return}
 const result=feed.results?.[i.id],recommendations=M.recommendations(i,result?.items||[],videos);
 const entries=[...(i.entries||[])].sort((a,b)=>b.date.localeCompare(a.date)||(b.createdAt||'').localeCompare(a.createdAt||''));
 const collected=new Map();for(const e of entries)for(const link of e.links||[]){const url=M.safeUrl(link.url);if(url&&!collected.has(url))collected.set(url,{...link,url,entry:e})}
 $('#civic-topics').innerHTML=`<div class="civic-topic" data-topic="${esc(i.id)}"><div class="civic-intro"><span class="civic-eyebrow">追蹤的入口</span><h3>${esc(i.name)}</h3><p>${esc(i.then||i.note||'哪些事件值得持續觀察？留下方向，讓來源與理解慢慢累積。')}</p><div class="meta"><span>${esc(i.scope)}</span><span>${esc(i.status)}</span><span>${(i.criteria||[]).length} 項追蹤指標</span><span>${esc(i.keys.join(' · '))}</span></div></div><div class="civic-paper"><div class="civic-row"><h4>從來源看這個議題</h4><button data-civic-entry="${esc(i.id)}">＋ 連結文章／影片</button></div><h5 class="civic-sources-heading">已收錄來源（${collected.size}）</h5><div class="civic-collected">${collected.size?[...collected.values()].map(link=>`<div class="civic-source"><div class="meta"><time>${esc(link.entry.date)}</time><span>${esc(link.entry.label)}</span></div><a href="${esc(link.url)}" target="_blank" rel="noopener noreferrer">↗ ${esc(link.title||link.url)}</a>${link.entry.text?`<blockquote>${esc(link.entry.text.slice(0,240))}${link.entry.text.length>240?'…':''}</blockquote>`:''}<button data-civic-entry="${esc(i.id)}" data-entry-id="${esc(link.entry.id)}">編輯來源與觀察</button></div>`).join(''):'<p class="civic-empty-sources">還沒有收錄來源。先留下值得回頭看的文章、影片與你的觀察。</p>'}</div><details class="civic-recommendations" data-detail="recommendations:${esc(i.id)}" ${opened.has('recommendations:'+i.id)?'open':''}><summary>推薦文章與影片（${recommendations.length}）<span>依關鍵字更新 · 展開挑選</span></summary><p class="muted">${result?.error?'本次新聞抓取失敗，保留先前推薦。':result?'來自公開新聞 RSS 與現有影片。':'等待下次更新後取得新聞，仍可自行新增來源。'}${result?.updated?' 新聞取得於 '+esc(date(result.updated))+'。':''} 推薦未經事實查核，不代表議題已有進展。</p>${recommendations.length?recommendations.map((item,index)=>`<div class="civic-recommendation"><div class="meta"><span>${esc(item.type||'文章')} · ${esc(item.source||'公開新聞')}</span><time>${Number.isFinite(Date.parse(item.published))?esc(date(item.published)):'日期未提供'}</time></div><a href="${esc(M.safeUrl(item.url))}" target="_blank" rel="noopener noreferrer">${esc(item.title)} ↗</a><button data-civic-collect="${index}" data-owner="${esc(i.id)}">＋ 收錄到記事</button></div>`).join(''):'<p class="muted">目前沒有符合關鍵字的推薦。</p>'}</details><div class="civic-understanding"><div class="civic-row"><h4>我的理解與追蹤方向</h4><button data-civic-edit="${esc(i.id)}">✎ 編輯</button></div><p>${esc(i.note||'還沒有留下自己的理解。按「編輯」整理你的觀察方向。')}</p><ol class="civic-criteria">${(i.criteria||[]).map(c=>`<li><span>${esc(c.text)}</span><button data-civic-progress="${esc(c.id)}" data-owner="${esc(i.id)}">${esc(c.status)} · 記錄</button></li>`).join('')}</ol><p class="civic-disclaimer">「待查證」表示仍需要整理佐證，不代表事情尚未發生。</p></div><details class="civic-history" data-detail="timeline:${esc(i.id)}" ${opened.has('timeline:'+i.id)?'open':''}><summary>觀察紀錄（${entries.length}） · 展開時間軸</summary><div class="civic-actions"><button data-civic-entry="${esc(i.id)}">＋ 新增觀察</button></div>${entries.map(e=>`<div class="civic-entry"><div class="meta"><time>${esc(e.date)}</time><span>${esc(e.label)}</span><button data-civic-entry="${esc(i.id)}" data-entry-id="${esc(e.id)}">編輯</button></div>${e.title?`<b>${esc(e.title)}</b>`:''}<p>${esc(e.text)}</p>${linksHtml(e.links)}</div>`).join('')||'<p class="muted">未來的消息、進展與判斷，依日期留在這裡。</p>'}</details></div></div>`;
 bindNavigation();
 root.querySelectorAll('[data-civic-edit]').forEach(b=>b.onclick=()=>openEditor(b.dataset.civicEdit));
 root.querySelectorAll('[data-civic-entry]').forEach(b=>b.onclick=()=>{editable(b.dataset.civicEntry);openEntry(b.dataset.civicEntry,b.dataset.entryId)});
 root.querySelectorAll('[data-civic-progress]').forEach(b=>b.onclick=()=>openProgress(b.dataset.owner,b.dataset.civicProgress));
 root.querySelectorAll('[data-civic-collect]').forEach(b=>b.onclick=()=>{
  const item=editable(b.dataset.owner),recommendation=M.recommendations(item,feed.results?.[item.id]?.items||[],videos)[Number(b.dataset.civicCollect)];
  openEntry(item.id);$('#entry-note-title').value=recommendation.title;$('#entry-links').value=recommendation.title+' | '+recommendation.url;$('#entry-text').value='來源重點：\n\n與追蹤方向的關聯：';
 });
};
function openEditor(id){editing=id||null;const i=id?topics().find(i=>i.id===id):null;$('#civic-editor-title').textContent=i?'編輯公共議題':'新增公共議題';$('#civic-name').value=i?.name||'';$('#civic-edit-scope').value=i?.scope||($('#civic-scope').value==='全部'?'中央':$('#civic-scope').value);$('#civic-keys').value=(i?.keys||[]).join(', ');$('#civic-note').value=i?.note||'';$('#civic-criteria').value=(i?.criteria||[]).map(c=>c.text).join('\n');$('#civic-status').value=i?.status||'觀察中';$('#civic-editor').showModal()}
$('#civic-add').onclick=()=>openEditor();$('#civic-cancel').onclick=()=>$('#civic-editor').close();
$('#civic-form').onsubmit=e=>{e.preventDefault();const keys=$('#civic-keys').value.split(/[,，]/).map(s=>s.trim()).filter(Boolean),name=$('#civic-name').value.trim(),lines=$('#civic-criteria').value;if(!name||!keys.length||!lines.trim())return;const i=editing?editable(editing):{id:crypto.randomUUID(),kind:'civic',entries:[],then:''};Object.assign(i,{name,scope:$('#civic-edit-scope').value,keys,note:$('#civic-note').value.trim(),status:$('#civic-status').value,criteria:M.criteria(lines,i.criteria||[],()=>crypto.randomUUID())});if(!editing)issues.push(i);activeTopic=i.id;$('#civic-scope').value=i.scope;localStorage.setItem('civic-selected-scope',i.scope);save();$('#civic-editor').close();renderIssues();};
const dialog=document.createElement('dialog');dialog.id='civic-progress-editor';dialog.innerHTML=`<form id="civic-progress-form"><h2>記錄指標進展</h2><p id="civic-progress-title"></p><label>狀態<select id="civic-progress-state">${M.states.map(s=>option(s)).join('')}</select></label><label>日期<input id="civic-progress-date" type="date" required></label><label>觀察與依據<textarea id="civic-progress-note" rows="3" required></textarea></label><label>佐證連結（每行：名稱 | 網址；標記已達成時必填）<textarea id="civic-progress-links" rows="3"></textarea></label><p id="civic-progress-error" role="alert"></p><button type="button" id="civic-progress-cancel">取消</button> <button type="submit">儲存進展</button></form>`;document.body.append(dialog);
function openProgress(id,cid){progress={id,cid};const c=topics().find(i=>i.id===id).criteria.find(c=>c.id===cid);$('#civic-progress-title').textContent=c.text;$('#civic-progress-state').value=c.status;$('#civic-progress-date').value=today();$('#civic-progress-note').value='';$('#civic-progress-links').value='';$('#civic-progress-error').textContent='';dialog.showModal()}
$('#civic-progress-cancel').onclick=()=>dialog.close();
$('#civic-progress-form').onsubmit=e=>{e.preventDefault();const links=[];for(const line of $('#civic-progress-links').value.split('\n').filter(s=>s.trim())){const pos=line.indexOf('|'),url=M.safeUrl((pos<0?line:line.slice(pos+1)).trim());if(!url){$('#civic-progress-error').textContent='請輸入有效的 http 或 https 來源連結。';return}links.push({title:pos<0?url:line.slice(0,pos).trim()||url,url})}const status=$('#civic-progress-state').value;if(status==='已達成'&&!links.length){$('#civic-progress-error').textContent='標記已達成前，請附至少一個佐證來源。';return}const i=editable(progress.id),c=i.criteria.find(c=>c.id===progress.cid),previous=c.status;c.status=status;c.updatedAt=new Date().toISOString();i.entries.push({id:crypto.randomUUID(),issueIds:[i.id],date:$('#civic-progress-date').value,createdAt:new Date().toISOString(),label:'進度紀錄',title:c.text,text:previous+' → '+status+'\n'+$('#civic-progress-note').value.trim(),links,country:'tw',region:'asia'});save();dialog.close();renderIssues()};
function selectScope(scope){$('#civic-scope').value=scope;localStorage.setItem('civic-selected-scope',scope);activeTopic=null;window.renderCivic()}
function bindNavigation(){root.querySelectorAll('[data-civic-city]').forEach(b=>b.onclick=()=>selectScope(b.dataset.civicCity));root.querySelectorAll('[data-civic-topic]').forEach(b=>b.onclick=()=>{activeTopic=b.dataset.civicTopic;window.renderCivic()})}
function setLandmark(scope){root.style.setProperty('--civic-landmark-position',['臺北市','高雄市','嘉義市'].includes(scope)?'center top':'center center');const credit=M.landmark(scope,landmarks);root.style.setProperty('--civic-landmark',credit?'url("'+credit.file+'")':'none');$('#civic-landmark-credit').innerHTML=credit?`${esc(credit.name)} · <a href="${esc(credit.source)}" target="_blank" rel="noopener noreferrer">${esc(credit.author)}</a> · <a href="${esc(M.safeUrl(credit.licenseUrl)||credit.source)}" target="_blank" rel="noopener noreferrer">${esc(credit.license)}</a> · 裁切淡化`:''}
fetch('landmarks/credits.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(data=>{landmarks=data;setLandmark($('#civic-scope').value)}).catch(()=>{});
$('#civic-scope').onchange=()=>selectScope($('#civic-scope').value);$('#civic-search').oninput=window.renderCivic;
$('#civic-sync-settings').onclick=()=>$('#sync-settings').click();
const syncStatus=()=>{$('#civic-sync-status').textContent=$('#sync-message').textContent||'編輯先存於本機；設定 GitHub 權杖後自動同步。'};
new MutationObserver(syncStatus).observe($('#sync-message'),{childList:true,subtree:true,characterData:true});syncStatus();
let loading=false;
window.loadCivicRecommendations=async()=>{if(loading)return;loading=true;try{const r=await fetch('public-news.json?t='+Date.now(),{cache:'no-store',signal:AbortSignal.timeout(20000)});if(!r.ok)throw Error();const data=await r.json();if(!Array.isArray(data.topics)||!data.results)throw Error();feed=data;feedError=''}catch{feedError='新聞推薦暫時讀取失敗；保留已載入的內容。請按上方「重新載入頁面資料」重試。'}finally{loading=false;window.renderCivic()}};
window.renderCivic();window.loadCivicRecommendations();
})();
